import { Component, EventEmitter } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { SelectedAriaAttributes, SheetAriaAttribute, SheetBackground, SheetDismissEventDetail, SheetMotionHiddenEndEventDetail, SheetMotionVisibleEndEventDetail } from '../types';

export type PSheetProps = {
  /**
   * Sets ARIA attributes on the sheet dialog element for improved accessibility when the default `aria-label` is insufficient.
   */
  aria?: SelectedAriaAttributes<SheetAriaAttribute>;
  /**
   * Sets the background color of the sheet panel (`canvas` or `surface`).
   * @default 'canvas'
   */
  background?: SheetBackground;
  /**
   * When enabled, clicking the backdrop will not close the sheet.
   * @default false
   */
  disableBackdropClick?: boolean;
  /**
   * Shows a dismiss button in the sheet header so users can manually close it.
   * @default true
   */
  dismissButton?: boolean;
  /**
   * Controls whether the sheet panel slides in from the bottom and is visible to the user.
   * @default false
   */
  open: boolean;
};

@Component({
  selector: 'p-sheet,[p-sheet]',
  template: '<ng-content />',
  inputs: ['aria', 'background', 'disableBackdropClick', 'dismissButton', 'open'],
  outputs: ['dismiss', 'motionHiddenEnd', 'motionVisibleEnd'],
  standalone: false
})
export class PSheet extends BaseComponent {
  aria?: SelectedAriaAttributes<SheetAriaAttribute>;
  background?: SheetBackground;
  disableBackdropClick?: boolean;
  dismissButton?: boolean;
  open!: boolean;
  dismiss = new EventEmitter<CustomEvent<SheetDismissEventDetail>>();
  motionHiddenEnd = new EventEmitter<CustomEvent<SheetMotionHiddenEndEventDetail>>();
  motionVisibleEnd = new EventEmitter<CustomEvent<SheetMotionVisibleEndEventDetail>>();
  
}