import { Component } from '@angular/core';
import { BaseComponent } from '../../utils';

export type PMultiSelectOptionProps = {
  /**
   * Disables the option, preventing it from being selected.
   * @default false
   */
  disabled?: boolean;
  /**
   * Sets the required option value submitted with the form data when selected. Must be a string or number.
   */
  value: string | number;
};

@Component({
  selector: 'p-multi-select-option,[p-multi-select-option]',
  template: '<ng-content />',
  inputs: ['disabled', 'value'],
  standalone: false
})
export class PMultiSelectOption extends BaseComponent {
  disabled?: boolean;
  value!: string | number;
  
}