import { Component } from '@angular/core';
import { BaseComponent } from '../../utils';

export type POptgroupProps = {
  /**
   * Disables all options in the group, preventing any of them from being selected.
   * @default false
   */
  disabled?: boolean;
  /**
   * Sets the visible group heading displayed above the grouped options.
   */
  label?: string;
};

@Component({
  selector: 'p-optgroup,[p-optgroup]',
  template: '<ng-content />',
  inputs: ['disabled', 'label'],
  standalone: false
})
export class POptgroup extends BaseComponent {
  disabled?: boolean;
  label?: string;
  
}