import { Component, EventEmitter } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { SelectedAriaAttributes, DrilldownAriaAttribute, DrilldownDismissEventDetail, DrilldownUpdateEventDetail } from '../types';

export type PDrilldownProps = {
  /**
   * Sets which `p-drilldown-item` (by `identifier`) is currently expanded to show its sub-navigation level.
   */
  activeIdentifier?: string | undefined;
  /**
   * Sets ARIA attributes on the drilldown dialog element for improved screen reader accessibility.
   */
  aria?: SelectedAriaAttributes<DrilldownAriaAttribute>;
  /**
   * Controls whether the drilldown navigation panel is visible.
   * @default false
   */
  open?: boolean;
};

@Component({
  selector: 'p-drilldown,[p-drilldown]',
  template: '<ng-content />',
  inputs: ['activeIdentifier', 'aria', 'open'],
  outputs: ['dismiss', 'update'],
  standalone: false
})
export class PDrilldown extends BaseComponent {
  activeIdentifier?: string | undefined;
  aria?: SelectedAriaAttributes<DrilldownAriaAttribute>;
  open?: boolean;
  dismiss = new EventEmitter<CustomEvent<DrilldownDismissEventDetail>>();
  update = new EventEmitter<CustomEvent<DrilldownUpdateEventDetail>>();
  
}