import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { SelectedAriaAttributes, CheckboxAriaAttribute, BreakpointCustomizable, CheckboxBlurEventDetail, CheckboxChangeEventDetail, CheckboxState } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

export type PCheckboxProps = {
  /**
   * Sets additional ARIA attributes on the native checkbox to improve accessibility for screen readers.
   */
  aria?: SelectedAriaAttributes<CheckboxAriaAttribute>;
  /**
   * Reflects the checkbox's current checked state and allows setting the initial checked value on load.
   * @default false
   */
  checked?: boolean;
  /**
   * Reduces the checkbox size and spacing for a more compact layout.
   * @default false
   */
  compact?: boolean;
  /**
   * Disables the checkbox, preventing all interaction. The value is not submitted with the form.
   * @default false
   */
  disabled?: boolean;
  /**
   * Associates the checkbox with a form element by its ID when not directly nested inside it.
   */
  form?: string;
  /**
   * Hides the visible label while keeping it accessible to screen readers. Supports responsive breakpoint values.
   * @default false
   */
  hideLabel?: BreakpointCustomizable<boolean>;
  /**
   * Puts the checkbox into an indeterminate state, indicating that a group of child items is only partially selected.
   * @default false
   */
  indeterminate?: boolean;
  /**
   * Sets the visible label text displayed next to the checkbox.
   * @default ''
   */
  label?: string;
  /**
   * @experimental Disables the checkbox and displays a loading spinner to indicate an ongoing operation.
   * @default false
   */
  loading?: boolean;
  /**
   * Sets the validation feedback message displayed below the checkbox when `state` is `success` or `error`.
   * @default ''
   */
  message?: string;
  /**
   * Sets the name submitted with the form data to identify this checkbox's value on the server.
   * @default ''
   */
  name?: string;
  /**
   * Marks the checkbox as required — form submission is blocked unless the checkbox is checked.
   * @default false
   */
  required?: boolean;
  /**
   * Sets the validation state, controlling the visual appearance and style of the feedback message (`none`, `success`, `error`).
   * @default 'none'
   */
  state?: CheckboxState;
  /**
   * Sets the value submitted with the form data when the checkbox is checked. Unchecked checkboxes are excluded from form submissions.
   * @default 'on'
   */
  value?: string;
};

@Component({
  selector: 'p-checkbox,[p-checkbox]',
  template: '<ng-content />',
  inputs: ['aria', 'checked', 'compact', 'disabled', 'form', 'hideLabel', 'indeterminate', 'label', 'loading', 'message', 'name', 'required', 'state', 'value'],
  outputs: ['blur', 'change'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PCheckbox),
      multi: true,
    },
  ],
  host: {
    '(change)': '_onChange($event.target.checked)',
    '(blur)': '_onTouched()'
  }
})
export class PCheckbox extends BaseComponent implements ControlValueAccessor {
  aria?: SelectedAriaAttributes<CheckboxAriaAttribute>;
  checked?: boolean;
  compact?: boolean;
  disabled?: boolean;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  indeterminate?: boolean;
  label?: string;
  loading?: boolean;
  message?: string;
  name?: string;
  required?: boolean;
  state?: CheckboxState;
  value?: string;
  blur = new EventEmitter<CustomEvent<CheckboxBlurEventDetail>>();
  change = new EventEmitter<CustomEvent<CheckboxChangeEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'checked', value ?? false);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}