import { Component } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { TextListType } from '../types';

export type PTextListProps = {
  /**
   * Sets the list type to either `unordered` (bulleted) or `ordered` (numbered), controlling the rendered HTML element (`ul` vs `ol`).
   * @default 'unordered'
   */
  type?: TextListType;
};

@Component({
  selector: 'p-text-list,[p-text-list]',
  template: '<ng-content />',
  inputs: ['type'],
  standalone: false
})
export class PTextList extends BaseComponent {
  type?: TextListType;
  
}