import { Component } from '@angular/core';
import { BaseComponent } from '../../utils';

export type PDrilldownItemProps = {
  /**
   * Private property set by the component itself.
   * @default false
   */
  cascade?: boolean;
  /**
   * Sets the unique identifier matched against the drilldown's `activeIdentifier` to determine if this item is shown.
   */
  identifier: string;
  /**
   * Sets the text used for the back button, sticky header, and cascade button that navigates into this navigation level.
   */
  label?: string;
  /**
   * Private property set by the component itself.
   * @default false
   */
  primary?: boolean;
  /**
   * Private property set by the component itself.
   * @default false
   */
  secondary?: boolean;
};

@Component({
  selector: 'p-drilldown-item,[p-drilldown-item]',
  template: '<ng-content />',
  inputs: ['cascade', 'identifier', 'label', 'primary', 'secondary'],
  standalone: false
})
export class PDrilldownItem extends BaseComponent {
  cascade?: boolean;
  identifier!: string;
  label?: string;
  primary?: boolean;
  secondary?: boolean;
  
}