import { Component, EventEmitter } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { SelectedAriaAttributes, ModalAriaAttribute, ModalBackdrop, ModalBackground, BreakpointCustomizable, ModalDismissEventDetail, ModalMotionHiddenEndEventDetail, ModalMotionVisibleEndEventDetail } from '../types';

export type PModalProps = {
  /**
   * Sets ARIA attributes on the dialog element for improved accessibility when no visible heading is present.
   */
  aria?: SelectedAriaAttributes<ModalAriaAttribute>;
  /**
   * Sets the backdrop style. Use `blur` when the modal is opened by user interaction; use `shading` when opened automatically (e.g. Cookie Consent).
   * @default 'blur'
   */
  backdrop?: ModalBackdrop;
  /**
   * Sets the background color of the modal panel (`canvas` or `surface`).
   * @default 'canvas'
   */
  background?: ModalBackground;
  /**
   * When enabled, clicking the backdrop will not close the modal.
   * @default false
   */
  disableBackdropClick?: boolean;
  /**
   * Shows a dismiss button in the modal header so the user can manually close it.
   * @default true
   */
  dismissButton?: boolean;
  /**
   * Expands the modal to the full viewport size, intended for mobile use cases. Supports responsive breakpoint values.
   * @default false
   */
  fullscreen?: BreakpointCustomizable<boolean>;
  /**
   * Controls whether the modal dialog is visible.
   * @default false
   */
  open: boolean;
};

@Component({
  selector: 'p-modal,[p-modal]',
  template: '<ng-content />',
  inputs: ['aria', 'backdrop', 'background', 'disableBackdropClick', 'dismissButton', 'fullscreen', 'open'],
  outputs: ['dismiss', 'motionHiddenEnd', 'motionVisibleEnd'],
  standalone: false
})
export class PModal extends BaseComponent {
  aria?: SelectedAriaAttributes<ModalAriaAttribute>;
  backdrop?: ModalBackdrop;
  background?: ModalBackground;
  disableBackdropClick?: boolean;
  dismissButton?: boolean;
  fullscreen?: BreakpointCustomizable<boolean>;
  open!: boolean;
  dismiss = new EventEmitter<CustomEvent<ModalDismissEventDetail>>();
  motionHiddenEnd = new EventEmitter<CustomEvent<ModalMotionHiddenEndEventDetail>>();
  motionVisibleEnd = new EventEmitter<CustomEvent<ModalMotionVisibleEndEventDetail>>();
  
}