import { Component, EventEmitter } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { StepperHorizontalUpdateEventDetail, BreakpointCustomizable, StepperHorizontalSize } from '../types';

export type PStepperHorizontalProps = {  /**
   * The font size of the step labels.
   * @default 'small'
   */
  size?: BreakpointCustomizable<StepperHorizontalSize>;
};

@Component({
  selector: 'p-stepper-horizontal,[p-stepper-horizontal]',
  template: '<ng-content />',
  inputs: ['size'],
  outputs: ['update'],
  standalone: false
})
export class PStepperHorizontal extends BaseComponent {
  size?: BreakpointCustomizable<StepperHorizontalSize>;
  update = new EventEmitter<CustomEvent<StepperHorizontalUpdateEventDetail>>();
  
}