import { Component, EventEmitter } from '@angular/core';
import { BaseComponent } from '../../utils';
import type { CanvasBackground, CanvasSidebarStartUpdateEventDetail } from '../types';

export type PCanvasProps = {
  /**
   * Sets the background color of the main content area and automatically applies a matching color to the sidebar.
   * @default 'canvas'
   */
  background?: CanvasBackground;
  /**
   * Controls whether the utility sidebar on the end side (right in LTR) is open or collapsed.
   * @default false
   */
  sidebarEndOpen?: boolean;
  /**
   * Controls whether the navigation sidebar on the start side (left in LTR) is open or collapsed.
   * @default false
   */
  sidebarStartOpen?: boolean;
};

@Component({
  selector: 'p-canvas,[p-canvas]',
  template: '<ng-content />',
  inputs: ['background', 'sidebarEndOpen', 'sidebarStartOpen'],
  outputs: ['sidebarEndDismiss', 'sidebarStartUpdate'],
  standalone: false
})
export class PCanvas extends BaseComponent {
  background?: CanvasBackground;
  sidebarEndOpen?: boolean;
  sidebarStartOpen?: boolean;
  sidebarEndDismiss = new EventEmitter<CustomEvent<void>>();
  sidebarStartUpdate = new EventEmitter<CustomEvent<CanvasSidebarStartUpdateEventDetail>>();
  
}